@RestController
public class UserController {                          // presentation: HTTP only
    private final UserService service;
    public UserController(UserService service) { this.service = service; }

    @GetMapping("/users/{id}")
    public UserResponse get(@PathVariable Long id) { return service.find(id); }
}

@Service
class UserService {                                    // business: rules, transactions
    private final UserRepository repo;
    UserService(UserRepository repo) { this.repo = repo; }

    UserResponse find(Long id) {
        return UserResponse.from(repo.findById(id).orElseThrow(() -> new UserNotFoundException(id)));
    }
}

interface UserRepository extends JpaRepository<User, Long> {}   // persistence

// WRONG: skips the service and its rules
@PostMapping("/orders")
public Order create(@RequestBody Order order) { return orderRepository.save(order); }

// RIGHT
@PostMapping("/orders")
public OrderResponse create(@Valid @RequestBody CreateOrderRequest req) { return orderService.create(req); }

// Synchronous: checkout depends on the email service being up
emailClient.sendConfirmation(order);

// Asynchronous: publish an event and move on
@Service
class OrderService {
    private final KafkaTemplate<String, OrderCreated> kafka;

    void complete(Order order) {
        repository.save(order);
        kafka.send("orders.created", order.id().toString(), OrderCreated.from(order));
    }
}

// WRONG: two systems, no shared transaction
repository.save(order);                  // saved
kafka.send("orders.created", event);     // fails -> event lost, stock never reserved

// RIGHT: write the event to an outbox table in the same transaction;
// a separate process publishes it (see "Distributed Transactions and Outbox")

